effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float l = gmLum(c);
  float sh = 1.0 - smoothstep(0.0, 0.55, l);
  float hi = smoothstep(0.42, 1.0, l);
  vec3 teal   = vec3(0.05, 0.42, 0.46);
  vec3 orange = vec3(1.00, 0.58, 0.20);
  vec3 g = c;
  g = mix(g, g * (teal * 2.1 + 0.30), sh * strength * (1.0 - balance * 0.5));
  g = mix(g, g * (orange * 1.7 + 0.18), hi * strength * (0.55 + balance * 0.6));
  float skin = smoothstep(0.15, 0.55, c.r) * (1.0 - smoothstep(0.55, 0.85, c.b));
  g = mix(g, c, skin * protectSkin);
  vec3 col = mix(c, clamp(g, 0.0, 1.0), mixAmt);
  gl_FragColor = vec4(col * a, a);
}
